-- ============================================================
-- 1. TABLE UTILISATEURS
-- ============================================================
CREATE TABLE utilisateurs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pseudo VARCHAR(100) NOT NULL UNIQUE,
    email VARCHAR(255) NOT NULL UNIQUE,
    telephone VARCHAR(20) NOT NULL UNIQUE,
    mot_de_passe_hash TEXT NOT NULL,
    ville VARCHAR(100),
    quartier VARCHAR(100),
    avatar_url TEXT,
    role VARCHAR(50) DEFAULT 'membre' CHECK (role IN ('membre', 'moderateur', 'admin')),
    date_inscription TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    derniere_connexion TIMESTAMP WITH TIME ZONE,
    est_actif BOOLEAN DEFAULT TRUE,
    tags_preferes TEXT[] DEFAULT '{}'
);

-- Index pour la recherche rapide des utilisateurs
CREATE INDEX idx_utilisateur_pseudo ON utilisateurs (pseudo);
CREATE INDEX idx_utilisateur_email ON utilisateurs (email);
CREATE INDEX idx_utilisateur_ville ON utilisateurs (ville);
CREATE INDEX idx_utilisateur_quartier ON utilisateurs (quartier);


-- ============================================================
-- 2. TABLE ANNONCES (avec contraintes et clé étrangère)
-- ============================================================
CREATE TABLE annonces (
    id VARCHAR(50) PRIMARY KEY,
    type VARCHAR(50) NOT NULL CHECK (type IN ('besoin', 'opportunite', 'rencontre', 'evenement', 'service')),
    sous_categorie VARCHAR(100),
    titre VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    lieu VARCHAR(255) NOT NULL,
    heure VARCHAR(50),
    date DATE DEFAULT CURRENT_DATE,
    auteur_id UUID NOT NULL REFERENCES utilisateurs(id) ON DELETE CASCADE,
    contact VARCHAR(100) NOT NULL,
    urgence VARCHAR(50) CHECK (urgence IN ('critique', 'elevee', 'moyenne', 'basse')),
    gain VARCHAR(100),
    type_aide VARCHAR(100),
    statut VARCHAR(50) DEFAULT 'ouvert' CHECK (statut IN ('ouvert', 'en_cours', 'clos')),
    date_creation TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    tags TEXT[] DEFAULT '{}',
    nombre_vues INT DEFAULT 0,
    nombre_reponses INT DEFAULT 0
);

-- Index pour la recherche rapide
CREATE INDEX idx_annonce_type ON annonces (type);
CREATE INDEX idx_annonce_urgence ON annonces (urgence);
CREATE INDEX idx_annonce_statut ON annonces (statut);
CREATE INDEX idx_annonce_date ON annonces (date);
CREATE INDEX idx_annonce_auteur ON annonces (auteur_id);
CREATE INDEX idx_annonce_lieu ON annonces (lieu);

-- Index pour la recherche plein texte (français)
CREATE INDEX idx_annonce_fts ON annonces USING GIN (to_tsvector('french', COALESCE(titre, '') || ' ' || COALESCE(description, '')));

-- Index pour les tags (recherche par mot-clé)
CREATE INDEX idx_annonce_tags ON annonces USING GIN (tags);


